export{ModalMarcaCtrl};function ModalMarcaCtrl($scope,$uibModalInstance,marcaSvc,tS,params){$scope.tipoRegistro=1,$scope.data={},params&&params.idMarca>0&&($scope.tipoRegistro=2,$scope.data=Object.assign({},params),$scope.showStatus=!params.estado),$scope.saveAndUpdate=function(){try{const tituloModal=1===$scope.tipoRegistro?"Guardar":"Actualizar";if(!$scope.data.descripcion)return void tS.toastr("warning","Ingrese la Descripción",tituloModal);showLoader(),$scope.data.idMarca>0?marcaSvc.update($scope.data.idMarca,$scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)}):marcaSvc.save($scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)})}catch(error){hideLoader(),console.log(error)}},$scope.successReponse=function(response){hideLoader(),"0"===response.code&&tS.toastr("warning",response.message,response.titleSms),"1"===response.code&&(tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response))},$scope.closeModal=function(){$uibModalInstance.close()}}ModalMarcaCtrl.$inject=["$scope","$uibModalInstance","marcaService","toastService","params"];